package com.aoo.bcg.common.repair;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class ClubReferenceRepairTransactionTest{static class Work implements ClubReferenceRepairTransaction.UnitOfWork{List<String>calls=new ArrayList<>();boolean valid=true;public void begin(){calls.add("begin");}public long lockClubVersion(long id){calls.add("lock");return 4;}public void repairMembers(long id){calls.add("members");}public void repairRoles(long id){calls.add("roles");}public void repairTemplates(long id){calls.add("templates");}public void repairTables(long id){calls.add("tables");}public void rebuildStatistics(long id){calls.add("statistics");}public boolean referencesValid(long id){calls.add("validate");return valid;}public long advanceVersion(long id,long v){calls.add("version");return v+1;}public void commit(){calls.add("commit");}public void rollback(){calls.add("rollback");}}@Test void repairsWholeAggregateBeforeAtomicCommit(){var work=new Work();assertEquals(5,new ClubReferenceRepairTransaction().execute(new ClubReferenceRepairTransaction.Request("r",7,4),work));assertEquals(List.of("begin","lock","members","roles","templates","tables","statistics","validate","version","commit"),work.calls);work=new Work();work.valid=false;var failed=work;assertThrows(IllegalStateException.class,()->new ClubReferenceRepairTransaction().execute(new ClubReferenceRepairTransaction.Request("r2",7,4),failed));assertEquals("rollback",work.calls.getLast());}}
